const facts=lesson.facts||[];
area.innerHTML=
'<section class="study-card story-card"><div class="section-tag">📖 FIRST • LEARN THE WHOLE LESSON</div><h2>Chapter Comprehension</h2><p class="story-lead">This is a detailed walk-through of the lesson. Read each part in order. Important names, meanings, events and textbook points are kept instead of reducing the chapter to a short summary.</p><div class="story-parts">'+story+'</div></section>'+
'<section class="study-card terms-card"><div class="section-tag">🧠 SECOND • WORDS & MEANINGS</div><h2>Important Words to Know</h2><div class="terms-grid">'+terms+'</div></section>'+
'<section class="study-card comprehension-card"><div class="section-tag">🔎 THIRD • COMPREHENSION</div><h2>Let’s Check the Whole Chapter</h2><p class="section-help">These questions deliberately cover different parts of the lesson. Type your answer first; only then will the textbook-aligned answer appear.</p>'+facts.map((f,i)=>'<div class="comp-item"><div class="comp-q"><span>'+(i+1)+'</span><b>'+esc(f[2])+'</b></div><input class="answer-input" placeholder="Type your answer…"><button class="check-answer" type="button" data-comp-index="'+i+'">Show textbook answer</button><div class="answer-slot"></div></div>').join("")+'</section>'+
'<section class="study-card exercises-card"><div class="section-tag">✍️ FOURTH • COMPLETE CHAPTER PRACTICE</div><h2>Exercises — Covering the Lesson in Full</h2><p class="section-help">The exercises are built from the full lesson coverage. The same fact is not intentionally repeated in every exercise type.</p>'+
'<div class="exercise-section"><h3>1. Fill in the Blanks</h3><p>Work through the chapter from beginning to end.</p>'+facts.map((f,i)=>'<div class="exercise-item"><div class="exercise-number">'+(i+1)+'</div><div class="exercise-main"><h3>'+esc(f[1])+'</h3><input class="answer-input" placeholder="Type your answer here…"><button class="check-answer" type="button" data-type="fill" data-index="'+i+'">Show textbook answer</button><div class="answer-slot"></div></div></div>').join("")+'</div>'+
'<div class="exercise-section"><h3>2. Match the Following</h3><p>Match important people, places, terms, events and ideas. The choices are shuffled.</p><div class="match-grid">'+facts.slice(0,Math.min(12,facts.length)).map((f,i)=>'<div class="match-row"><div class="match-left"><span>'+(i+1)+'</span><b>'+esc(f[0])+'</b></div><select class="match-select"><option value="">Choose…</option>'+facts.slice(0,Math.min(12,facts.length)).map((g,j)=>'<option value="'+j+'">'+String.fromCharCode(65+j)+'. '+esc(g[2])+'</option>').join("")+'</select></div>').join("")+'</div><button id="checkMatch" class="match-check" type="button">Check my matching</button><div id="matchResult"></div></div>'+
'<div class="exercise-section"><h3>3. Answer in One Word</h3><p>Use the shortest accurate answer you can.</p>'+facts.map((f,i)=>'<div class="exercise-item"><div class="exercise-number">'+(i+1)+'</div><div class="exercise-main"><h3>'+esc(f[2])+'</h3><input class="answer-input" placeholder="Type one word…"><button class="check-answer" type="button" data-type="word" data-index="'+i+'">Show textbook answer</button><div class="answer-slot"></div></div></div>').join("")+'</div>'+
'<div class="exercise-section"><h3>4. Answer in One Sentence</h3><p>Explain the point clearly in one sentence.</p>'+facts.map((f,i)=>'<div class="exercise-item"><div class="exercise-number">'+(i+1)+'</div><div class="exercise-main"><h3>'+esc(f[2])+'</h3><input class="answer-input" placeholder="Type one sentence…"><button class="check-answer" type="button" data-type="sentence" data-index="'+i+'">Show textbook answer</button><div class="answer-slot"></div></div></div>').join("")+'</div></section>'+
'<nav class="chapter-nav"><a class="nav-btn" href="'+(id>1?"catechism-quiz.html?lesson="+(id-1):"#")+'" '+(id===1?'aria-disabled="true"':'')+'>← Previous Chapter</a><a class="all-chapters" href="catechism.html">All 8 Chapters</a><a class="nav-btn" href="'+(id<8?"catechism-quiz.html?lesson="+(id+1):"#")+'" '+(id===8?'aria-disabled="true"':'')+'>Next Chapter →</a></nav>';
area.querySelectorAll(".check-answer").forEach(btn=>btn.addEventListener("click",()=>{
const item=btn.closest(".comp-item,.exercise-item"),input=item.querySelector(".answer-input");if(!input.value.trim()){input.focus();return}
const i=Number(btn.dataset.compIndex??btn.dataset.index),answer=facts[i][btn.dataset.compIndex!==undefined?4:(btn.dataset.type==="sentence"?4:3)];
item.querySelector(".answer-slot").innerHTML=reveal(answer);btn.disabled=true;input.classList.add("attempted");
}));
